"use strict";
import { useAccount } from "hooks/useAccount";
import { useMemo, useCallback } from "react";
import { useGaugeForPool, useUserGaugeData } from "./useGaugeData";
import { useGaugeRewards } from "./useGaugeRewards";
import { useWriteContract, useReadContract } from "wagmi";
import { contractAddresses, contractABIs } from "uniswap/src/constants/cl-contracts";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { ethers } from "ethers";
import { useEthersProvider } from "hooks/useEthersProvider";
import { useQueryClient } from "@tanstack/react-query";
export function useGaugeStaking(position) {
  const { address, chainId } = useAccount();
  const provider = useEthersProvider({ chainId });
  const queryClient = useQueryClient();
  const isTestnet = chainId === UniverseChainId.AbstractTestnet;
  const isMainnet = chainId === UniverseChainId.AbstractMainnet;
  const networkContracts = isTestnet ? { addresses: contractAddresses.abstractTestnet, abis: contractABIs.abstractTestnet } : isMainnet ? { addresses: contractAddresses.abstractMainnet, abis: contractABIs.abstractMainnet } : null;
  const gaugeAddress = position ? useGaugeForPool(position.poolId).gauge?.id : null;
  const { writeContractAsync } = useWriteContract();
  const V2_GAUGE_ABI = [
    {
      "inputs": [{ "internalType": "uint256", "name": "_amount", "type": "uint256" }],
      "name": "deposit",
      "outputs": [],
      "stateMutability": "nonpayable",
      "type": "function"
    },
    {
      "inputs": [{ "internalType": "uint256", "name": "_amount", "type": "uint256" }],
      "name": "withdraw",
      "outputs": [],
      "stateMutability": "nonpayable",
      "type": "function"
    },
    {
      "inputs": [{ "internalType": "address", "name": "_account", "type": "address" }],
      "name": "getReward",
      "outputs": [],
      "stateMutability": "nonpayable",
      "type": "function"
    },
    {
      "inputs": [{ "internalType": "address", "name": "", "type": "address" }],
      "name": "balanceOf",
      "outputs": [{ "internalType": "uint256", "name": "", "type": "uint256" }],
      "stateMutability": "view",
      "type": "function"
    }
  ];
  const { data: isApprovedForAll } = useReadContract({
    address: networkContracts?.addresses.NonfungiblePositionManager,
    abi: networkContracts?.abis.NonfungiblePositionManager,
    functionName: "isApprovedForAll",
    args: address && gaugeAddress ? [address, gaugeAddress] : void 0,
    enabled: Boolean(networkContracts?.abis.NonfungiblePositionManager && address && gaugeAddress && position?.version === ProtocolVersion.V3),
    watch: true
  });
  const { data: v2Allowance } = useReadContract({
    address: position?.poolId,
    abi: [
      {
        "inputs": [
          { "internalType": "address", "name": "owner", "type": "address" },
          { "internalType": "address", "name": "spender", "type": "address" }
        ],
        "name": "allowance",
        "outputs": [{ "internalType": "uint256", "name": "", "type": "uint256" }],
        "stateMutability": "view",
        "type": "function"
      }
    ],
    functionName: "allowance",
    args: address && gaugeAddress ? [address, gaugeAddress] : void 0,
    enabled: Boolean(position?.poolId && address && gaugeAddress && position?.version === ProtocolVersion.V2),
    watch: true
  });
  const isV3Approved = Boolean(isApprovedForAll);
  const isV2Approved = v2Allowance ? parseFloat(v2Allowance.toString()) > 0 : false;
  const isApproved = position?.version === ProtocolVersion.V3 ? isV3Approved : isV2Approved;
  const { gauge, hasGauge, isLoading: gaugeLoading } = useGaugeForPool(position?.poolId);
  const { data: userGaugeData, isLoading: userDataLoading } = useUserGaugeData();
  const gaugeRewards = useGaugeRewards(position, gauge?.id);
  const gaugeData = useMemo(() => {
    if (!position || !address) {
      return {
        stakedAmount0: "0",
        stakedAmount1: "0",
        unstakedAmount0: position?.currency0Amount?.toFixed(4) || "0",
        unstakedAmount1: position?.currency1Amount?.toFixed(4) || "0",
        pendingRewards: gaugeRewards?.earnedRewards || "0",
        apr: gaugeRewards?.apr || "N/A",
        isStaked: false,
        canStake: Boolean(position?.currency0Amount && position?.currency1Amount && hasGauge),
        gaugeAddress: gauge?.id || null,
        isLoading: gaugeLoading || userDataLoading
      };
    }
    const userStake = userGaugeData?.stakes?.find(
      (stake) => stake.gauge.id.toLowerCase() === gauge?.id.toLowerCase()
    );
    const positionIsStaked = Boolean(position?.isStaked);
    const contractIsStaked = gaugeRewards?.isStaked || false;
    const subgraphIsStaked = Boolean(userStake && parseFloat(userStake.amount) > 0);
    const isStaked = positionIsStaked || contractIsStaked || subgraphIsStaked;
    const contractStakedAmount = parseFloat(gaugeRewards?.stakedBalance || "0");
    const subgraphStakedAmount = userStake ? parseFloat(userStake.amount) / 1e18 : 0;
    const stakedAmount = contractStakedAmount > 0 ? contractStakedAmount : subgraphStakedAmount;
    const apr = gaugeRewards?.apr || "N/A";
    const totalAmount0 = parseFloat(position.currency0Amount?.toFixed(4) || "0");
    const totalAmount1 = parseFloat(position.currency1Amount?.toFixed(4) || "0");
    let stakedAmount0 = "0";
    let stakedAmount1 = "0";
    let unstakedAmount0 = totalAmount0.toFixed(4);
    let unstakedAmount1 = totalAmount1.toFixed(4);
    if (position.isPartiallyStaked) {
      const stakingPercentage = (position.stakingPercentage || 0) / 100;
      stakedAmount0 = (totalAmount0 * stakingPercentage).toFixed(4);
      stakedAmount1 = (totalAmount1 * stakingPercentage).toFixed(4);
      unstakedAmount0 = (totalAmount0 * (1 - stakingPercentage)).toFixed(4);
      unstakedAmount1 = (totalAmount1 * (1 - stakingPercentage)).toFixed(4);
    } else if (isStaked) {
      stakedAmount0 = totalAmount0.toFixed(4);
      stakedAmount1 = totalAmount1.toFixed(4);
      unstakedAmount0 = "0";
      unstakedAmount1 = "0";
    }
    return {
      stakedAmount0,
      stakedAmount1,
      unstakedAmount0,
      unstakedAmount1,
      pendingRewards: gaugeRewards?.earnedRewards || "0",
      apr,
      isStaked,
      canStake: Boolean(position.currency0Amount && position.currency1Amount && hasGauge && !isStaked),
      gaugeAddress: gauge?.id || null,
      isLoading: gaugeLoading || userDataLoading,
      // Additional reward stats
      rewardRate: gaugeRewards?.rewardRate || "0",
      totalSupply: gaugeRewards?.totalSupply || "0",
      rawStakedBalance: gaugeRewards?.raw?.stakedBalance || "0"
    };
  }, [position, address, gauge, hasGauge, userGaugeData, gaugeLoading, userDataLoading, gaugeRewards]);
  const stakePosition = useCallback(async (tokenId) => {
    console.log("\u{1F525} [STAKE DEBUG] Attempting to stake:", {
      tokenId,
      hasGaugeAddress: !!gaugeData.gaugeAddress,
      gaugeAddress: gaugeData.gaugeAddress,
      hasPosition: !!position,
      poolId: position?.poolId,
      hasGauge,
      gauge: gauge?.id
    });
    if (!gaugeData.gaugeAddress || !position) {
      console.error("\u274C [STAKE DEBUG] Missing requirements:", {
        gaugeAddress: gaugeData.gaugeAddress,
        position: !!position,
        hasGauge,
        actualGaugeId: gauge?.id
      });
      throw new Error("No gauge available for this pool");
    }
    const isV3 = position.version === ProtocolVersion.V3;
    try {
      if (!isApproved) {
        if (isV3 && position.tokenId) {
          const approvalTx = await writeContractAsync({
            address: networkContracts?.addresses.NonfungiblePositionManager,
            abi: networkContracts?.abis.NonfungiblePositionManager,
            functionName: "setApprovalForAll",
            args: [gaugeData.gaugeAddress, true]
          });
          popupRegistry.addPopup({ type: PopupType.Transaction, hash: approvalTx }, approvalTx);
        } else {
          const MAX_UINT256 = "115792089237316195423570985008687907853269984665640564039457584007913129639935";
          const approvalTx = await writeContractAsync({
            address: position?.poolId,
            // V2 pool address is the LP token
            abi: [
              {
                "inputs": [
                  { "internalType": "address", "name": "spender", "type": "address" },
                  { "internalType": "uint256", "name": "amount", "type": "uint256" }
                ],
                "name": "approve",
                "outputs": [{ "internalType": "bool", "name": "", "type": "bool" }],
                "stateMutability": "nonpayable",
                "type": "function"
              }
            ],
            functionName: "approve",
            args: [gaugeData.gaugeAddress, BigInt(MAX_UINT256)]
          });
          popupRegistry.addPopup({ type: PopupType.Transaction, hash: approvalTx }, approvalTx);
        }
        await new Promise((resolve) => setTimeout(resolve, 2e3));
      }
      let txHash;
      if (isV3 && position.tokenId) {
        txHash = await writeContractAsync({
          address: gaugeData.gaugeAddress,
          abi: networkContracts?.abis.CLGauge,
          functionName: "deposit",
          args: [BigInt(position.tokenId)]
        });
      } else {
        const walletBalance = position.balance || position.liquidityAmount?.quotient?.toString() || "0";
        console.log("\u{1F527} [V2 STAKING] Using wallet LP balance:", {
          walletBalance,
          liquidityAmount: position.liquidityAmount?.toExact(),
          positionBalance: position.balance,
          gaugeAddress: gaugeData.gaugeAddress,
          poolId: position.poolId
        });
        if (!walletBalance || walletBalance === "0" || Number(walletBalance) === 0) {
          throw new Error("No LP tokens found in wallet to stake. Position may already be staked.");
        }
        txHash = await writeContractAsync({
          address: gaugeData.gaugeAddress,
          abi: V2_GAUGE_ABI,
          functionName: "deposit",
          args: [BigInt(walletBalance)]
        });
      }
      popupRegistry.addPopup({ type: PopupType.Transaction, hash: txHash }, txHash);
      console.log("\u{1F504} [STAKING] Invalidating queries after successful stake...");
      await queryClient.invalidateQueries({ queryKey: ["positions-service-oriented"] });
      await queryClient.invalidateQueries({ queryKey: ["user-gauge-data"] });
      await queryClient.invalidateQueries({ queryKey: ["pool-data"] });
      await queryClient.invalidateQueries({ queryKey: ["available-gauges-with-pools"] });
      setTimeout(() => {
        console.log("\u{1F504} [STAKING] Force refetching queries after delay...");
        queryClient.refetchQueries({ queryKey: ["positions-service-oriented"] });
        queryClient.refetchQueries({ queryKey: ["user-gauge-data"] });
      }, 2e3);
    } catch (error) {
      console.error("Staking failed:", error);
      throw error;
    }
  }, [gaugeData.gaugeAddress, position, queryClient]);
  const unstakePosition = useCallback(async (tokenId) => {
    if (!gaugeData.gaugeAddress || !position || !address) {
      throw new Error("No gauge available for this pool or missing wallet address");
    }
    const isV3 = position.version === ProtocolVersion.V3;
    try {
      let txHash;
      if (isV3 && position.tokenId) {
        txHash = await writeContractAsync({
          address: gaugeData.gaugeAddress,
          abi: networkContracts?.abis.CLGauge,
          functionName: "withdraw",
          args: [BigInt(position.tokenId)]
        });
      } else {
        console.log("\u{1F527} [V2 UNSTAKING] Querying real-time staked balance from gauge contract...");
        const gaugeContract = new ethers.Contract(
          gaugeData.gaugeAddress,
          V2_GAUGE_ABI,
          provider
        );
        const stakedBalance = await gaugeContract.balanceOf(address);
        const stakedAmountToWithdraw = stakedBalance.toString();
        console.log("\u{1F527} [V2 UNSTAKING] Real-time gauge balance query result:", {
          gaugeAddress: gaugeData.gaugeAddress,
          userAddress: address,
          stakedBalance: stakedAmountToWithdraw,
          stakedBalanceFormatted: ethers.utils.formatEther(stakedBalance)
        });
        if (!stakedBalance || stakedBalance.eq(0)) {
          throw new Error("No staked balance found to withdraw. Position may not be staked or already unstaked.");
        }
        txHash = await writeContractAsync({
          address: gaugeData.gaugeAddress,
          abi: V2_GAUGE_ABI,
          functionName: "withdraw",
          args: [stakedBalance]
          // Use the exact balance from contract
        });
      }
      popupRegistry.addPopup({ type: PopupType.Transaction, hash: txHash }, txHash);
      console.log("\u{1F504} [UNSTAKING] Invalidating queries after successful unstake...");
      await queryClient.invalidateQueries({ queryKey: ["positions-service-oriented"] });
      await queryClient.invalidateQueries({ queryKey: ["user-gauge-data"] });
      await queryClient.invalidateQueries({ queryKey: ["pool-data"] });
      await queryClient.invalidateQueries({ queryKey: ["available-gauges-with-pools"] });
      setTimeout(() => {
        console.log("\u{1F504} [UNSTAKING] Force refetching queries after delay...");
        queryClient.refetchQueries({ queryKey: ["positions-service-oriented"] });
        queryClient.refetchQueries({ queryKey: ["user-gauge-data"] });
      }, 2e3);
    } catch (error) {
      console.error("Unstaking failed:", error);
      throw error;
    }
  }, [gaugeData.gaugeAddress, position, address, provider, networkContracts, queryClient]);
  const claimRewards = useCallback(async (tokenId) => {
    if (!gauge?.id || !position) {
      throw new Error("No gauge available for this pool");
    }
    const isV3 = position.version === ProtocolVersion.V3;
    try {
      let txHash;
      if (isV3 && position.tokenId) {
        txHash = await writeContractAsync({
          address: gauge.id,
          abi: networkContracts?.abis.CLGauge,
          functionName: "getReward",
          args: [BigInt(position.tokenId)]
        });
      } else {
        if (!address) {
          throw new Error("User address not available for V2 reward claiming");
        }
        txHash = await writeContractAsync({
          address: gauge.id,
          abi: V2_GAUGE_ABI,
          functionName: "getReward",
          args: [address]
        });
      }
      popupRegistry.addPopup({ type: PopupType.Transaction, hash: txHash }, txHash);
      queryClient.invalidateQueries({ queryKey: ["user-gauge-data"] });
      queryClient.invalidateQueries({ queryKey: ["gauge-rewards"] });
    } catch (error) {
      console.error("Reward claim failed:", error);
      throw error;
    }
  }, [gauge?.id, position, networkContracts, writeContractAsync, address, queryClient]);
  return {
    ...gaugeData,
    stakePosition,
    unstakePosition,
    claimRewards,
    isApproved,
    needsApproval: !isApproved && hasGauge && Boolean(position)
  };
}
export function useGaugeAPR(poolAddress) {
  const { gauge, isLoading } = useGaugeForPool(poolAddress);
  return useMemo(() => {
    if (!poolAddress || !gauge) {
      return { apr: "N/A", isLoading };
    }
    if (gauge.rewardRate && gauge.totalSupply) {
      const rewardRatePerSecond = parseFloat(gauge.rewardRate) / 1e18;
      const totalStaked = parseFloat(gauge.totalSupply) / 1e18;
      if (totalStaked > 0) {
        const yearlyRewards = rewardRatePerSecond * 31536e3;
        const aprValue = yearlyRewards / totalStaked * 100;
        return {
          apr: aprValue.toFixed(2),
          isLoading
        };
      }
    }
    return {
      apr: "0",
      isLoading
    };
  }, [poolAddress, gauge, isLoading]);
}
export function useUserGaugePositions(userAddress) {
  const { data: userGaugeData, isLoading } = useUserGaugeData();
  return useMemo(() => {
    if (!userAddress || !userGaugeData) {
      return {
        positions: [],
        totalStaked: "0",
        totalRewards: "0",
        isLoading
      };
    }
    const positions = userGaugeData.stakes?.map((stake) => ({
      gaugeAddress: stake.gauge.id,
      poolAddress: stake.gauge.pool,
      stakedAmount: (parseFloat(stake.amount) / 1e18).toFixed(4),
      pendingRewards: "0",
      // TODO: Calculate from claims data
      apr: "N/A",
      // Not available from current schema
      tokenId: stake.id
    })) || [];
    const totalStaked = positions.reduce((sum, pos) => sum + parseFloat(pos.stakedAmount), 0).toFixed(4);
    const totalRewards = userGaugeData.claims?.reduce((sum, claim) => sum + parseFloat(claim.amount) / 1e18, 0).toFixed(4) || "0";
    return {
      positions,
      totalStaked,
      totalRewards,
      isLoading
    };
  }, [userAddress, userGaugeData, isLoading]);
}
